loginUrl:
function checkLogin(){
var r=java.connect('https://www.wenku8.net/userdetail.php');
var b=String(r.body());
var hasForm=b.indexOf('frmlogin')>=0;
if(!hasForm){java.longToast('已登录');return;}
java.longToast('未登录：搜索/榜单/分类需登录，请点[1.登录账号]按钮');}
function login(){
var result=source.getLoginInfoMap();
var u=String(result.get('username')||'');
var p=String(result.get('password')||'');
if(!u||!p){java.longToast('请先填写用户名(或邮箱)和密码');return;}
var body='username='+u+'&password='+p+'&usecookie=315360000&action=login&submit=%20%B5%C7%20%C2%BC%20';
var opt=String.fromCharCode(44,123,34,109,101,116,104,111,100,34,58,34,80,79,83,84,34,44,34,99,104,97,114,115,101,116,34,58,34,71,66,75,34,44,34,98,111,100,121,34,58,34);
var r=java.connect('https://www.wenku8.net/login.php?do=submit'+opt+body+String.fromCharCode(34,125));
var b=String(r.body());
if(b.indexOf('frmlogin')>=0){java.longToast('登录失败：用户名或密码错误');}
else{
var ck=cookie.getCookie('https://www.wenku8.net');
if(ck.indexOf('jieqiUserInfo')>=0){
source.putLoginHeader(JSON.stringify({Cookie:ck}));
java.longToast('登录成功：'+u);
}else{java.longToast('登录响应正常但未取得会话Cookie，请重试');}
}}
function logout(){
source.putLoginHeader('');
cookie.removeCookie('https://www.wenku8.net');
java.longToast('已退出登录');}

