ruleBookInfo.init:
@js:(function(){
var h=String(result);
function pick(p){var g=h.match(p);return g?g[1]:'';}
var g1=h.match(/<b>([^<]+)<\/b>\[<a/);var nm=g1?g1[1]:'';
var au=pick(/小说作者：([^<]+)</);
var ct=pick(/文库分类：([^<]+)</);
var st=pick(/文章状态：([^<]+)</);
var up=pick(/最后更新：([^<]+)</);
var wd=pick(/文章字数：([^<]+)</);
var g2=h.match(/作品Tags：([^<]+)<\/b>/);var tg=g2?g2[1]:'';
var g3=h.match(/内容简介：<\/span><br ?\/?><span style="font-size:14px;">([\s\S]*?)<\/span>/);
var it='';
if(g3){it=g3[1];
var NL=String.fromCharCode(10);
it=it.split('<br />').join(NL).split('<br/>').join(NL).split('<br>').join(NL);
it=it.replace(/<[^>]+>/g,'');
}
var g4=h.match(/<img src="(http:\/\/img\.wenku8\.com\/[^"]+)"/);
var cv=g4?g4[1]:'';
if(!cv){var g4b=h.match(/<img src="([^"]*\/image\/[^"]+)"/);cv=g4b?g4b[1]:'';}
if(cv.indexOf('http')!==0){cv='http://img.wenku8.com'+(cv.charAt(0)==='/'?'':'/')+cv;}
var g5=h.match(/aid=(\d+)/);var aid=g5?g5[1]:'';
var toc=aid?'/modules/article/reader.php?aid='+aid:'';
if(!toc){var g5n=h.match(/href="(\/novel\/[^"]+index\.htm)"/);if(g5n)toc=g5n[1];}
var off=(h.indexOf('因版权问题')>=0)?1:0;
var o={};
o.name=nm;o.author=au;o.kind=ct+'·'+st;
var g6=h.match(/<a href="[^"]*cid=(\d+)"[^>]*>([^<]+)<\/a>/);
o.lastChapter=g6?g6[2]:'';
o.intro=it+(off?'\n[站点公告] 因版权问题，本书在线阅读已下架':'');
o.coverUrl=cv;o.tocUrl=toc;
o.init='aid\u0001'+(h.match(/addbookcase\.php\?bid=(\d+)/)||['',''])[1]+'\u0001'+up+'\u0001'+tg+'\u0001'+off;
return JSON.stringify(o);})()

ruleToc.chapterList:
@js:(function(){
var h=String(result), L=[];
var NL=String.fromCharCode(10);
var volRe=/<td class="vcss"[^>]*>([\s\S]*?)<\/td>/g;
var volM, vols=[];
while((volM=volRe.exec(h))!==null){vols.push({p:volM.index,n:volM[1].trim()});}
var re=/<td class="ccss"><a href="[^"]*aid=(\d+)&cid=(\d+)"[^>]*>([\s\S]*?)<\/a><\/td>/g;
var m, vi=0;
while((m=re.exec(h))!==null){
while(vi<vols.length && m.index>vols[vi+1?vi+1:0]&&false)vi=vi;
while(vi+1<vols.length && m.index>vols[vi+1].p)vi++;
var vn=vi<vols.length?vols[vi].n:'';
var t=m[3].trim();
var o={};
o.name=(vn?vn+' ':'')+t;
o.url='https://www.wenku8.net/modules/article/reader.php?aid='+m[1]+'&cid='+m[2];
L.push(JSON.stringify(o));
}
if(L.length===0){
var cn=h.match(/cid=(\d+)"[^>]*>/);
if(!cn&&h.indexOf('vcss')<0){
throw new Error('目录获取失败：未找到任何章节。可能本书已下架或页面结构变化');
}}
return L;})()

ruleContent.content:
@js:(function(){
var h=String(result);
var i=h.indexOf('<div id="content">');
if(i<0){throw new Error('正文获取失败：页面结构异常(可能被站点限流，请稍后重试)');}
var seg=h.substring(i+18);
var j=seg.indexOf('<div id="footlink">');
if(j>0)seg=seg.substring(0,j);
var NL=String.fromCharCode(10);
var g=h.match(/<div id="title">([^<]*)<\/div>/);
var ti=g?g[1].trim():'';
var imgs=[];
var im=/<div class="divimage"><a href="[^"]*"[^>]*><img src="([^"]+)"/g;
var mm;
while((mm=im.exec(seg))!==null){imgs.push(mm[1]);}
if(imgs.length>0){
var IQ=String.fromCharCode(34);
var out='<img src='+IQ+imgs[0]+IQ+' style="display:block;max-width:100%;">';
for(var k=1;k<imgs.length;k++){out+=NL+'<img src='+IQ+imgs[k]+IQ+' style="display:block;max-width:100%;">';}
return out;
}
seg=seg.split('<ul id="contentdp">').join('');
seg=seg.split('</ul>').join('');
var lines=seg.split('<br />');
var out=[];
for(var k2=0;k2<lines.length;k2++){
var t=lines[k2].replace(/<[^>]*>/g,'');
t=t.split('&nbsp;').join(' ');
t=t.split('&#12539;').join('·');
t=t.split('&middot;').join('·');
t=t.replace(/&[a-zA-Z]+;/g,'');
t=t.replace(/&#\d+;/g,'');
t=t.replace(/^[\s\u3000]+/,'').replace(/[\s\u3000]+$/,'');
if(!t)continue;
if(t.indexOf('本文来自')>=0)continue;
if(t.indexOf('轻小说文库(http')>=0)continue;
if(t.indexOf('为你一网打尽')>=0)continue;
if(t.indexOf('轻之国度')>=0)continue;
if(t.indexOf('天使动漫')>=0)continue;
if((t.indexOf('录入')>=0||t.indexOf('扫图')>=0||t.indexOf('图源')>=0||t.indexOf('修图')>=0)&&t.length<40)continue;
out.push(t);
}
var r='';
for(var k3=0;k3<out.length;k3++){r+=out[k3]+NL;}
return ti?ti+NL+NL+r:r;})()
